function isPlainObject(value) {
    if (value === null || typeof value !== "object" || Array.isArray(value))
        return false;
    const proto = Object.getPrototypeOf(value);
    return proto === Object.prototype || proto === null;
}
export function merge_dicts_recursively(...dicts) {
    const result = {};
    for (const dict of dicts) {
        for (const [key, value] of Object.entries(dict)) {
            if (key in result && isPlainObject(result[key]) && isPlainObject(value)) {
                result[key] = merge_dicts_recursively(result[key], value);
            }
            else {
                result[key] = value;
            }
        }
    }
    return result;
}
export function update_dict_recursively(current_dict, ...others) {
    const updated = merge_dicts_recursively(current_dict, ...others);
    for (const [key, value] of Object.entries(updated)) {
        current_dict[key] = value;
    }
}
